"""Generate Python gRPC stubs. .NET stubs are generated by Grpc.Tools at build time."""

from __future__ import annotations

import re
import shutil
import sys
from pathlib import Path

from grpc_tools import protoc

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "src/python/switchboard_inference/gen"


def main() -> int:
    shutil.rmtree(OUT, ignore_errors=True)
    OUT.mkdir(parents=True)
    include = Path(protoc.__file__).parent / "_proto"
    protos = [str(p) for p in (ROOT / "proto").rglob("*.proto")]
    code = protoc.main(
        ["protoc", f"-I{ROOT / 'proto'}", f"-I{include}", f"--python_out={OUT}", f"--grpc_python_out={OUT}", *protos]
    )
    if code != 0:
        return code
    # protoc emits absolute imports; rewrite them so the package is relocatable.
    for path in OUT.rglob("*.py"):
        text = re.sub(
            r"^from switchboard\.v1 import",
            "from switchboard_inference.gen.switchboard.v1 import",
            path.read_text(encoding="utf-8"),
            flags=re.M,
        )
        path.write_text(text, encoding="utf-8")
    for directory in [OUT, OUT / "switchboard", OUT / "switchboard/v1"]:
        (directory / "__init__.py").touch()
    return 0


if __name__ == "__main__":
    sys.exit(main())
